comment on column ssr_ingest.anchor_tiles_stage.ssr_level is 'Legacy ingest compatibility marker retained from the earlier 2,001-era contract. It is not the canonical vertical-layer count. Canonical vertical authority is ecology.ssr_vertical_11001_layers with 11,001 layers.';
alter table sourcecubes.cube_bindings add column if not exists spatial_cube_id uuid references public.spatial_cubes(id) on delete restrict;
alter table sourcecubes.cube_bindings add column if not exists anchor_candidate_id uuid references ecology.ssr_anchor_candidate_registry(id) on delete restrict;
alter table sourcecubes.cube_bindings add column if not exists anchor_tile_id text references public.anchor_tiles(anchor_tile_id) on delete restrict;
alter table sourcecubes.cube_bindings add column if not exists canonical_address text;
alter table sourcecubes.cube_bindings add column if not exists latitude double precision;
alter table sourcecubes.cube_bindings add column if not exists longitude double precision;
alter table sourcecubes.cube_bindings add column if not exists altitude_m integer;
alter table sourcecubes.cube_bindings add column if not exists macro_layer text;
alter table sourcecubes.cube_bindings add column if not exists vertical_datum text not null default 'EGM96';
alter table sourcecubes.cube_bindings add column if not exists authority_state text not null default 'CANDIDATE';
alter table sourcecubes.cube_bindings add column if not exists canonical_identity_authority boolean not null default false;
alter table sourcecubes.cube_bindings add column if not exists temporal_identity_mode text not null default 'STATIC_SPATIAL_IDENTITY_DYNAMIC_EVIDENCE';
alter table sourcecubes.cube_bindings add column if not exists dca_role text not null default 'OPTIONAL_GOVERNANCE_METADATA';
create unique index if not exists sourcecubes_cube_binding_candidate_z_uq on sourcecubes.cube_bindings(anchor_candidate_id,z_index) where anchor_candidate_id is not null;
create unique index if not exists sourcecubes_cube_binding_anchor_z_uq on sourcecubes.cube_bindings(anchor_tile_id,z_index) where anchor_tile_id is not null;
create unique index if not exists sourcecubes_cube_binding_spatial_cube_uq on sourcecubes.cube_bindings(spatial_cube_id) where spatial_cube_id is not null;
comment on column sourcecubes.cube_bindings.ssr_registry_id is 'Legacy compatibility link. Modern canonical SourceCube identity uses public.spatial_cubes + public.anchor_tiles + ecology.ssr_vertical_11001_layers.';
create table if not exists sourcecubes.cube_evidence_bindings(evidence_binding_id uuid primary key default gen_random_uuid(),cube_uid text not null references sourcecubes.cube_bindings(cube_uid) on delete cascade,domain text not null check(domain in ('AIR','LAND','SEA','SUBSURFACE','CROSS_DOMAIN')),evidence_role text not null,provider_code text,source_schema text not null,source_table text not null,source_record_id text not null,observed_at timestamptz,requested_latitude double precision,requested_longitude double precision,grid_latitude double precision,grid_longitude double precision,observed_z_index integer,spatial_association_state text not null,vertical_authority_state text not null default 'NONCANONICAL_EVIDENCE',canonical_identity_authority boolean not null default false,physical_impact_authority boolean not null default false,official_warning_authority boolean not null default false,evidence_reference text,evidence_payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(source_schema,source_table,source_record_id,cube_uid,evidence_role));
create or replace function sourcecubes.bind_cube_evidence(p_cube_uid text,p_domain text,p_evidence_role text,p_provider_code text,p_source_schema text,p_source_table text,p_source_record_id text,p_observed_at timestamptz,p_spatial_association_state text,p_evidence_reference text,p_evidence_payload jsonb default '{}'::jsonb) returns uuid language plpgsql set search_path='pg_catalog','sourcecubes' as $$ declare v_id uuid; begin if not exists(select 1 from sourcecubes.cube_bindings where cube_uid=p_cube_uid) then raise exception 'Unknown SourceCube UID'; end if; if p_domain not in ('AIR','LAND','SEA','SUBSURFACE','CROSS_DOMAIN') then raise exception 'Invalid SourceCube evidence domain'; end if; insert into sourcecubes.cube_evidence_bindings(cube_uid,domain,evidence_role,provider_code,source_schema,source_table,source_record_id,observed_at,spatial_association_state,evidence_reference,evidence_payload) values(p_cube_uid,p_domain,p_evidence_role,p_provider_code,p_source_schema,p_source_table,p_source_record_id,p_observed_at,p_spatial_association_state,p_evidence_reference,coalesce(p_evidence_payload,'{}'::jsonb)) on conflict(source_schema,source_table,source_record_id,cube_uid,evidence_role) do update set observed_at=excluded.observed_at,evidence_reference=excluded.evidence_reference,evidence_payload=excluded.evidence_payload returning evidence_binding_id into v_id; return v_id; end $$;
create or replace view sourcecubes.cube_4d_state as select b.cube_uid,b.canonical_address,b.anchor_candidate_id,b.anchor_tile_id,b.z_index,b.altitude_m,b.macro_layer,b.vertical_datum,b.binding_status,b.authority_state,b.canonical_identity_authority,count(e.evidence_binding_id) evidence_count,count(*) filter(where e.domain='AIR') air_evidence_count,count(*) filter(where e.domain='LAND') land_evidence_count,count(*) filter(where e.domain='SEA') sea_evidence_count,count(*) filter(where e.domain='SUBSURFACE') subsurface_evidence_count,min(e.observed_at) earliest_evidence_time,max(e.observed_at) latest_evidence_time,bool_or(e.canonical_identity_authority) any_evidence_claims_identity_authority from sourcecubes.cube_bindings b left join sourcecubes.cube_evidence_bindings e on e.cube_uid=b.cube_uid group by b.cube_uid,b.canonical_address,b.anchor_candidate_id,b.anchor_tile_id,b.z_index,b.altitude_m,b.macro_layer,b.vertical_datum,b.binding_status,b.authority_state,b.canonical_identity_authority;
comment on view sourcecubes.cube_4d_state is 'Static canonical spatial identity plus time-varying observational evidence. Dynamic AIR/LAND/SEA evidence never confers canonical identity authority.';
